using Microsoft.ML.Data;

namespace TicketClassifier.Models;

/// <summary>
/// Input schema matching the training CSV.
/// </summary>
public sealed class TicketInput
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    public string Category { get; set; } = string.Empty;
}

/// <summary>
/// Output schema produced by the trained model.
/// </summary>
public sealed class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string PredictedCategory { get; set; } = string.Empty;

    public float[] Score { get; set; } = [];
}

namespace TicketClassifier.Models;

public sealed class TicketRequest
{
    public required string Subject { get; init; }
    public required string Description { get; init; }
    public int Priority { get; init; } = 2;
}

namespace TicketClassifier.Models;

public sealed class TicketClassificationResult
{
    public required string PredictedCategory { get; init; }
    public required Dictionary<string, float> Confidence { get; init; }
}

using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

/// <summary>
/// Trains and evaluates the ticket classification model at startup,
/// then saves it to disk for PredictionEnginePool to load.
/// </summary>
public sealed class TicketModelTrainer
{
    public const string ModelPath = "Data/ticket_model.zip";

    private static readonly string[] CategoryLabels = ["Billing", "General", "Technical"];

    public static void TrainAndSave(ILogger logger)
    {
        var mlContext = new MLContext(seed: 42);

        var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
        IDataView data = mlContext.Data.LoadFromTextFile<TicketInput>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        // Featurize text columns and combine with Priority into a single Features vector
        var pipeline = mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketInput.Category))
            .Append(mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketInput.Subject)))
            .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketInput.Description)))
            .Append(mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
            .Append(mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        logger.LogInformation("Training ticket classification model...");
        var model = pipeline.Fit(split.TrainSet);

        // Evaluate on held-out test set
        var predictions = model.Transform(split.TestSet);
        var metrics = mlContext.MulticlassClassification.Evaluate(predictions, "Label");

        LogMetrics(logger, metrics);

        // Re-train on all data for the production model
        var productionModel = pipeline.Fit(data);

        var modelSavePath = Path.Combine(AppContext.BaseDirectory, ModelPath);
        mlContext.Model.Save(productionModel, data.Schema, modelSavePath);
        logger.LogInformation("Model saved to {Path}", modelSavePath);
    }

    private static void LogMetrics(ILogger logger, MulticlassClassificationMetrics m)
    {
        logger.LogInformation("=== Model Evaluation Metrics ===");
        logger.LogInformation("  Macro Accuracy:    {MacroAccuracy:F4}", m.MacroAccuracy);
        logger.LogInformation("  Micro Accuracy:    {MicroAccuracy:F4}", m.MicroAccuracy);
        logger.LogInformation("  Log-Loss:          {LogLoss:F4}", m.LogLoss);
        logger.LogInformation("  Log-Loss Reduction:{LogLossReduction:F4}", m.LogLossReduction);

        logger.LogInformation("  Per-class metrics:");
        for (var i = 0; i < m.PerClassLogLoss.Count && i < CategoryLabels.Length; i++)
        {
            logger.LogInformation("    {Category}: LogLoss={LogLoss:F4}",
                CategoryLabels[i], m.PerClassLogLoss[i]);
        }
    }
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public sealed class TicketsController(
    PredictionEnginePool<TicketInput, TicketPrediction> predictionPool,
    ILogger<TicketsController> logger) : ControllerBase
{
    private static readonly string[] Categories = ["Billing", "General", "Technical"];

    /// <summary>
    /// Classifies a support ticket into Billing, Technical, or General.
    /// </summary>
    [HttpPost("classify")]
    public ActionResult<TicketClassificationResult> Classify([FromBody] TicketRequest request)
    {
        var input = new TicketInput
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority,
        };

        var prediction = predictionPool.Predict(input);

        var confidence = new Dictionary<string, float>();
        for (var i = 0; i < prediction.Score.Length && i < Categories.Length; i++)
        {
            confidence[Categories[i]] = prediction.Score[i];
        }

        logger.LogInformation(
            "Ticket classified as {Category} (confidence: {Confidence:F2}%)",
            prediction.PredictedCategory,
            confidence.GetValueOrDefault(prediction.PredictedCategory) * 100);

        return Ok(new TicketClassificationResult
        {
            PredictedCategory = prediction.PredictedCategory,
            Confidence = confidence,
        });
    }
}

